import { Chat } from "chat";
import { createSlackAdapter } from "@chat-adapter/slack";
import { createTeamsAdapter } from "@chat-adapter/teams";
import { createMemoryState } from "@chat-adapter/state-memory";

let bot;
const calls = [];

function getBot(env) {
  if (bot) return bot;
  bot = new Chat({
    userName: "surveybeat",
    logger: "silent",
    state: createMemoryState(),
    adapters: {
      slack: createSlackAdapter({
        botToken: "xoxb-test",
        signingSecret: env.SLACK_SIGNING_SECRET,
        apiUrl: "http://127.0.0.1:9/api/",
      }),
      teams: createTeamsAdapter({
        appId: "00000000-0000-0000-0000-000000000000",
        appPassword: "x",
        appType: "MultiTenant",
      }),
    },
  });
  bot.onSlashCommand("/pulse", async (event) => {
    calls.push({ command: event.command, text: event.text, user: event.user.userId });
  });
  return bot;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const b = getBot(env);
    const waitUntil = (p) => ctx.waitUntil(p);
    try {
      if (url.pathname === "/slack") return await b.webhooks.slack(request, { waitUntil });
      if (url.pathname === "/teams") return await b.webhooks.teams(request, { waitUntil });
      if (url.pathname === "/calls") return Response.json(calls);
      return new Response("ok");
    } catch (e) {
      return new Response("ERR " + (e && e.stack ? e.stack : String(e)), { status: 500 });
    }
  },
};

