import { createHmac } from "node:crypto";

const base = "http://127.0.0.1:8788";
const secret = "REDACTED";

async function show(label, res) {
  const text = await res.text();
  console.log(label, res.status, text.slice(0, 600).replace(/\n/g, " | "));
}

await show("root", await fetch(base + "/"));

const body = new URLSearchParams({
  token: "x", team_id: "T1", team_domain: "acme", channel_id: "C1", channel_name: "general",
  user_id: "U1", user_name: "ann", command: "/pulse", text: "health",
  response_url: "http://127.0.0.1:9/resp", trigger_id: "1.2.3", api_app_id: "A1",
}).toString();
const ts = Math.floor(Date.now() / 1000).toString();
const sig = "v0=" + createHmac("sha256", secret).update(`v0:${ts}:${body}`).digest("hex");
const headers = { "content-type": "application/x-www-form-urlencoded", "x-slack-request-timestamp": ts };

await show("slack bad sig", await fetch(base + "/slack", { method: "POST", headers: { ...headers, "x-slack-signature": "v0=00" }, body }));
const oldTs = (Math.floor(Date.now() / 1000) - 600).toString();
const oldSig = "v0=" + createHmac("sha256", secret).update(`v0:${oldTs}:${body}`).digest("hex");
await show("slack stale ts", await fetch(base + "/slack", { method: "POST", headers: { ...headers, "x-slack-request-timestamp": oldTs, "x-slack-signature": oldSig }, body }));
await show("slack good sig", await fetch(base + "/slack", { method: "POST", headers: { ...headers, "x-slack-signature": sig }, body }));
await new Promise((r) => setTimeout(r, 500));
await show("calls", await fetch(base + "/calls"));

const activity = { type: "message", id: "1", text: "hi", serviceUrl: "https://smba.trafficmanager.net/teams/", channelId: "msteams", from: { id: "29:x" }, conversation: { id: "a:1" }, recipient: { id: "28:x" } };
await show("teams no auth", await fetch(base + "/teams", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(activity) }));
await show("teams bad jwt", await fetch(base + "/teams", { method: "POST", headers: { "content-type": "application/json", authorization: "Bearer REDACTED" }, body: JSON.stringify(activity) }));

